import re, glob
TONE = {'info': 'neutral', 'success': 'positive', 'warning': 'caution'}
SIMPLE = re.compile(r"^[A-Za-z_$][\w$]*(\??\.[A-Za-z_$][\w$]*|\[[^\]]*\]|\([^()]*\))*$")


def balanced(s):
    d = 0
    for c in s:
        if c == '(':
            d += 1
        elif c == ')':
            d -= 1
            if d < 0:
                return False
    return d == 0


def neg(e):
    e = e.strip()
    if e == 'true': return 'false'
    if e == 'false': return 'true'
    if e.startswith('!'):
        r = e[1:].strip()
        if r.startswith('(') and r.endswith(')') and balanced(r[1:-1]): return r[1:-1]
        if SIMPLE.match(r): return r
    if SIMPLE.match(e): return '!' + e
    return '!(%s)' % e


ATTR = re.compile(r"""(\s+)(\[?)(label|variant|disableTooltip)(\]?)\s*=\s*("([^"]*)"|'([^']*)')""")
TAG = re.compile(r"<app-pill(?=[\s/>])")
LIT = re.compile(r"'(info|success|warning)'")
TERN = re.compile(r"[^?:]*\?\s*'[^']*'\s*:\s*('[^']*'|[^?:]*\?\s*'[^']*'\s*:\s*'[^']*')\s*")


def find_end(s, i):
    q = None
    while True:
        c = s[i]
        if q:
            if c == q: q = None
        elif c in '"\'': q = c
        elif c == '>': return i
        i += 1


def conv(s):
    out = []; pos = 0; pipe = False
    for m in TAG.finditer(s):
        if m.start() < pos: continue
        e = find_end(s, m.end())
        tag = s[m.start():e + 1]
        selfclose = tag.endswith('/>')
        body = tag[:-2] if selfclose else tag[:-1]
        st = {'label': None}

        def rep(a):
            nonlocal pipe
            ws, br, name, _, raw, d, sq = a.groups()
            val = d if d is not None else sq
            q = '"' if d is not None else "'"
            if name == 'label':
                st['label'] = ('{{ %s }}' % val.strip()) if br else val
                return ''
            if name == 'disableTooltip':
                return '%s[tooltip]=%s%s%s' % (ws, q, neg(val), q)
            if not br:
                return '%stone=%s%s%s' % (ws, q, TONE[val], q)
            v = val.strip()
            if re.fullmatch(r"'[^']*'", v) or TERN.fullmatch(v):
                return '%s[tone]=%s%s%s' % (ws, q, LIT.sub(lambda x: "'%s'" % TONE[x.group(1)], val), q)
            pipe = True
            return '%s[tone]=%s%s | pillTone%s' % (ws, q, v, q)

        body = ATTR.sub(rep, body)
        assert st['label'] is not None, tag
        rest = s[e + 1:]
        mm = re.match(r"\s*</app-pill>", rest)
        end = e + 1 + (mm.end() if mm else 0)
        out.append(s[pos:m.start()])
        if selfclose: body = body.rstrip()
        out.append(body + '>' + st['label'] + '</app-pill>')
        pos = end
    out.append(s[pos:])
    return ''.join(out), pipe


for f in glob.glob('features/**/*', recursive=True):
    if not f.endswith(('.ts', '.html')): continue
    s = open(f).read()
    if not TAG.search(s): continue
    n, pipe = conv(s)
    open(f, 'w').write(n)
    if pipe:
        ts = f if f.endswith('.ts') else f[:-5] + '.ts'
        t = open(ts).read()
        t = t.replace('imports: [ PillComponent,', 'imports: [ PillComponent, PillTonePipe,', 1)
        t = t.replace('from "../../lib/pill.component";', 'from "../../lib/pill.component";\nimport { PillTonePipe } from "../../lib/pill-tone.pipe";', 1)
        assert 'PillTonePipe,' in t and 'pill-tone.pipe' in t, ts
        open(ts, 'w').write(t)

